import sys, csv, numpy as np, pymc as pm
FAM = sys.argv[1]
src = open('../../../models/factor_graded_multiples_concepts.py').read()
N=100; NUMS=np.arange(1,101)
def family(f):
    out=[]
    if f=='residue':
        for m in range(3,13):
            if m==10: continue
            for r in range(1,m): out.append(NUMS % m == r)
    if f=='prog':
        for s in range(2,13):
            for a in range(1,101):
                if a+s<=100: out.append((NUMS>=a)&((NUMS-a)%s==0))
    if f=='digsum':
        ds=np.array([sum(map(int,str(n))) for n in NUMS])
        for k in range(1,19): out.append(ds==k)
    if f=='repdig':
        out.append(np.isin(NUMS,[11,22,33,44,55,66,77,88,99]))
    if f=='endunion':
        for a in range(10):
            for b in range(a+1,10): out.append(np.isin(NUMS%10,[a,b]))
    if f=='bprog':  # bounded progressions a..b step s, s 2..12, >=3 members
        for s in range(2,13):
            for a in range(1,101):
                for b in range(a+2*s,101,s): out.append((NUMS>=a)&(NUMS<=b)&((NUMS-a)%s==0))
    if f=='none': out.append(NUMS<0)
    return np.array(out,dtype=float)
EX=family(FAM)
src = src.replace('MEMBER = np.vstack([RULES, INTERVALS])','MEMBER = np.vstack([RULES, EXTRA, INTERVALS])')
