src = src.replace('    log_prior = pt.concatenate([pt.log(lam) + rule_logp, pt.log1p(-lam) + int_logp])',
'''    newc = pm.Normal("new_cost", 0.0, 5.0)
    ex_lp = -cost*(2.0) - newc + pt.zeros(N_EX)
    allr = pt.concatenate([rule_logp, ex_lp]); allr = allr - pt.logsumexp(allr)
    log_prior = pt.concatenate([pt.log(lam) + allr, pt.log1p(-lam) + int_logp])''')
src = src.replace('    rule_logp = rule_logp - pt.logsumexp(rule_logp)  # normalised within rules\n','')
g={'EXTRA':EX,'__name__':'v'}
exec(src.replace('import numpy as np','import numpy as np\nEXTRA=__EX__').replace('__EX__','EXTRA_IN'), {**g,'EXTRA_IN':EX})
EOF
echo

